import data from "@/lib/assessment-catalog.json";
import type { LStr } from "./i18n";

/** Build-time catalog of the built-in assessments (generated by backend/scripts/export-catalog.ts). */
export type CatalogTemplate = {
  slug: string; sort: number; name: LStr; summary: LStr; audience: LStr; evaluates: LStr[]; seo: { title: LStr; description: LStr };
  minutes: number; questions: number; categories: { key: string; name: LStr; description?: LStr }[];
};
export const catalog = data.templates as CatalogTemplate[];
export const bySlug = (slug: string) => catalog.find((t) => t.slug === slug);
